#!/usr/bin/env python3
"""Capture the flag with policies trained by reinforcement learning (PPO). One node per robot (~role).

Generated by rl/export_ctf.py (attacker: ctf_zero_robusto/att.pt; defender: ctf_zero_robusto/def.pt).
Do not edit by hand: train again and export. Documentation: rl/docs/documentacao.md

  attacker: MLP 38 -> 128 -> 128 -> 2 (tanh), trained against frozen defenders (and scripts)
  defender: MLP 38 -> 128 -> 128 -> 2 (tanh), trained against frozen attackers (and scripts)
The two roles were trained in alternation (rl/ctf_league.sh); with DEF_SCRIPT the defender is scripted. Everything is computed in the team frame
(red sees the arena rotated by 180 deg), so the same file plays blue or red (~team). It reads the
odometry of the four robots, both flags, /hero_N/has_flag and /game/state (held robots, carriers,
round time). Made for 2 x 2; with -n 2 the missing robots are assumed at their bases.
Only standard Python, numpy, rospy, the ROS messages and psr_hero.utils are used.

Run:  ./run.sh run ctf blue:=ctf_rl.py red:=none
"""
import base64
import json
import math

import numpy as np
import rospy
from geometry_msgs.msg import PointStamped, Twist
from nav_msgs.msg import Odometry
from std_msgs.msg import Bool, String

from psr_hero.utils import V_MAX, W_MAX, clamp, pose_from_odom, wrap_angle

CONTROL_HZ = 20
HALF = 0.8  # arena 1.6 x 1.6 m
BASE_X = 0.62  # m, blue base at -BASE_X, red at +BASE_X
HOLD_TIME, IMMUNE_TIME, ROUND_TIME = 4.0, 1.5, 90.0  # s (kit rules)
DEF_SCRIPT = False  # True: hybrid node, the defender is the scripted reference (ctf_script.py)
GUARD_FLAG = False  # True: the scripted defender stands exactly on its flag
DEF_GATE = None  # float: the defender network plays only while no active opponent has x < DEF_GATE


# --- observation (copied from rl/ctf_obs.py) --------------------------------
def team_frame_np(p, flip):
    """(x, y, yaw, v, w) of a robot in the team frame (flip=True for the red team)."""
    if not flip:
        return p
    yaw = (p[2] + 2.0 * math.pi) % (2.0 * math.pi) - math.pi
    return (-p[0], -p[1], yaw, p[3], p[4])


def observation_np(role, mine, theirs, own_flag, enemy_flag, carry, flag_taken, hold, immune, round_t, prev):
    """Same as observation_torch for one robot. mine, theirs: 2 tuples (x, y, yaw, v, w) in the team frame,
    in role order; flags (x, y) in the team frame; carry: 2 bools (my attacker, my defender carry the enemy
    flag); hold, immune: 4 remaining seconds (my att, my def, their att, their def). Returns 38 floats."""
    me, mate = mine[role], mine[1 - role]
    c, s = math.cos(me[2]), math.sin(me[2])

    def rel(px, py):
        dx, dy = px - me[0], py - me[1]
        return c * dx + s * dy, -s * dx + c * dy

    out = [me[0] / HALF, me[1] / HALF, c, s, me[3] / V_MAX, me[4] / W_MAX]
    for p in (enemy_flag, own_flag, (-BASE_X, 0.0), (BASE_X, 0.0), mate, theirs[0], theirs[1]):
        out += list(rel(p[0], p[1]))
    for o in theirs:
        out += [math.cos(o[2] - me[2]), math.sin(o[2] - me[2])]
    out += [float(bool(carry[role])), float(bool(carry[1 - role])), float(bool(flag_taken))]
    order = (role, 1 - role, 2, 3)
    out += [hold[k] / HOLD_TIME for k in order]
    out += [immune[k] / IMMUNE_TIME for k in order]
    out += [round_t / ROUND_TIME, float(prev[0]), float(prev[1])]
    return out


